use num_derive::{FromPrimitive, ToPrimitive};
use serde::{Deserialize, Serialize};
use strum_macros::{Display, EnumCount, EnumIter, EnumString};

pub use jrpg_engine::items::ItemKind;

// The `ItemId` enum is generated by `pokered-data/build.rs` from
// `data/items/item_list.json` (see `generate_item_enum`): `NoItem = 0x00`, the
// canonical list order keeps its byte IDs (0x01..=0x53), items added through
// the editor are appended after the base list, and Hm01-05 / Tm01-50 keep
// their fixed 0xC4..=0xFA ids. The derive set is emitted fully-qualified into
// the generated file; the `use` lines above remain for the hand-written
// enums below (`CustomKind`, `HmId`, `TmId`, `ItemEffect`, `ShopId`).
include!(concat!(env!("OUT_DIR"), "/items_gen.rs"));

pub const NUM_ITEMS: u8 = 0x53;
/// Highest GB item id (TM50 = $FA); TM/HM ids live above NUM_ITEMS.
pub const MAX_ITEM_ID: u8 = 0xFA;

impl ItemId {
    pub fn from_id(id: u8) -> Self {
        num_traits::FromPrimitive::from_u8(id).unwrap_or(ItemId::NoItem)
    }

    /// SCREAMING_SNAKE constant name matching the original asm item constants
    /// (e.g. `ItemId::OaksParcel` -> "OAKS_PARCEL", `PokeBall` -> "POKE_BALL",
    /// `SilphScope` -> "SILPH_SCOPE", `LiftKey` -> "LIFT_KEY").
    ///
    /// Derived from the PascalCase variant name (via `Debug`): a `_` is inserted
    /// before each interior uppercase letter or digit-run boundary, then the whole
    /// string is upper-cased. Best-effort for vitamin/TM-style names; key items —
    /// which is what scripts gate on — round-trip exactly.
    pub fn const_name(&self) -> String {
        let variant = format!("{:?}", self);
        let chars: Vec<char> = variant.chars().collect();
        let mut out = String::with_capacity(chars.len() + 4);
        for (i, &c) in chars.iter().enumerate() {
            if i > 0 {
                let prev = chars[i - 1];
                // Insert a separator at a "case/kind boundary":
                //   lower|digit -> Upper   (Poke|Ball, X|Accuracy)
                //   Upper       -> digit   (Unused|2C, Tm|01-style)
                let boundary = (c.is_ascii_uppercase() && !prev.is_ascii_uppercase())
                    || (c.is_ascii_digit() && prev.is_ascii_alphabetic());
                if boundary {
                    out.push('_');
                }
            }
            out.push(c.to_ascii_uppercase());
        }
        out
    }

    /// Inverse of [`const_name`](Self::const_name): find the item whose
    /// `const_name()` equals `name`. Returns `None` for unknown names or `NoItem`.
    ///
    /// Matching is underscore-insensitive, so both `"TM_34"` (the canonical
    /// `const_name`) and `"TM34"` resolve to `ItemId::Tm34` (likewise `HM01`,
    /// `X_ACCURACY`/`XACCURACY`). Scripts authored from the asm constants use the
    /// underscore-free `TM`/`HM` spelling, so accept it.
    pub fn from_const_name(name: &str) -> Option<Self> {
        let want: String = name.chars().filter(|c| *c != '_').collect();
        (0u8..=MAX_ITEM_ID).map(Self::from_id).find(|i| {
            *i != ItemId::NoItem
                && i.const_name().chars().filter(|c| *c != '_').collect::<String>() == want
        })
    }

    pub fn is_badge(self) -> bool {
        let v = self as u8;
        v >= 0x15 && v <= 0x1C
    }

    pub fn is_key_item(self) -> bool {
        matches!(
            self,
            ItemId::TownMap
                | ItemId::Bicycle
                | ItemId::Surfboard
                | ItemId::Pokedex
                | ItemId::OldAmber
                | ItemId::SecretKey
                | ItemId::BikeVoucher
                | ItemId::CardKey
                | ItemId::SsTicket
                | ItemId::GoldTeeth
                | ItemId::CoinCase
                | ItemId::OaksParcel
                | ItemId::Itemfinder
                | ItemId::SilphScope
                | ItemId::PokeFlute
                | ItemId::LiftKey
                | ItemId::OldRod
                | ItemId::GoodRod
                | ItemId::SuperRod
                | ItemId::DomeFossil
                | ItemId::HelixFossil
        )
    }
}

// ── CustomKind — game-specific item category extensions ───────────────────

/// Game-specific item kind extensions for Pokémon Red/Blue.
///
/// These categories are NOT universal to all JRPGs, so they live here
/// rather than in the engine's [`ItemKind`] enum.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum CustomKind {
    /// Capture devices (Poké Balls, Great Balls, etc.)
    Ball,
    /// Technical Machines — one-time-use move teachers
    Tm,
    /// Hidden Machines — reusable move teachers
    Hm,
}

// Gen 1 has no equipment system, so pokered does not implement the engine's
// optional `EquipProvider` trait. A Gen 2+ port would implement it to model
// the Held Item slot.

// ── item_kind ──────────────────────────────────────────────────────────────

/// Classify an item into its generic category.
///
/// Returns the engine-standard [`ItemKind`] for each Gen 1 item.
/// Items unique to Pokémon (balls, TMs, key items) use [`Custom`](ItemKind::Custom).
pub fn item_kind(id: ItemId) -> ItemKind<CustomKind> {
    use ItemId::*;
    match id {
        // Recovery items
        Potion | SuperPotion | HyperPotion | MaxPotion
        | FreshWater | SodaPop | Lemonade
        | Antidote | BurnHeal | IceHeal | Awakening | ParlyzHeal
        | FullHeal | FullRestore => ItemKind::Consumable,

        // Revives
        Revive | MaxRevive => ItemKind::Consumable,

        // Vitamins
        HpUp | Protein | Iron | Carbos | Calcium => ItemKind::StatBoost,
        RareCandy => ItemKind::StatBoost,

        // Evolution stones
        MoonStone | FireStone | ThunderStone | WaterStone | LeafStone => ItemKind::Evolution,

        // PP restoration
        Ether | MaxEther | Elixer | MaxElixer | PpUp => ItemKind::Consumable,

        // Battle items
        XAccuracy | XAttack | XDefend | XSpeed | XSpecial
        | DireHit | GuardSpec => ItemKind::Consumable,
        PokeDoll => ItemKind::Consumable,

        // Repel
        Repel | SuperRepel | MaxRepel => ItemKind::Consumable,

        // Escape
        EscapeRope => ItemKind::Consumable,

        // Capture devices (Pokémon-specific → Custom)
        MasterBall | UltraBall | GreatBall | PokeBall | SafariBall => {
            ItemKind::Custom(CustomKind::Ball)
        }

        // Key items
        Bicycle | TownMap | Surfboard | Pokedex
        | OldAmber | SecretKey | BikeVoucher | CardKey
        | SsTicket | GoldTeeth | CoinCase | OaksParcel
        | Itemfinder | SilphScope | PokeFlute | LiftKey
        | OldRod | GoodRod | SuperRod
        | DomeFossil | HelixFossil => ItemKind::KeyItem,

        // Currency items
        Nugget => ItemKind::Currency,

        // Technical / Hidden Machines — move-teaching items, storable in the bag.
        Hm01 | Hm02 | Hm03 | Hm04 | Hm05 => ItemKind::Custom(CustomKind::Hm),
        id if (id as u8) >= 0xC9 && (id as u8) <= 0xFA => ItemKind::Custom(CustomKind::Tm),

        // Badges, unused items, and anything else → KeyItem by default
        _ => ItemKind::KeyItem,
    }
}

