// ── ItemEffect — describes what an item does ───────────────────────────

/// Describes the combat / field effect of an item.
///
/// This enum bridges the gap between the abstract [`jrpg_engine::items::ItemProvider`]
/// trait and the concrete Pokémon Red/Blue item effects.  The actual application
/// of effects to a [`Pokemon`] lives in `pokered-core::items` because the data
/// crate cannot reference types from `pokered-core`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ItemEffect {
    /// Heal a fixed amount of HP (Potion = 20, Super Potion = 50, etc.).
    Heal(u32),
    /// Heal HP to full (Max Potion).
    FullHeal,
    /// Heal HP to full and cure all status (Full Restore).
    FullRestore,
    /// Revive a fainted Pokémon. `true` = full HP (Max Revive), `false` = half HP.
    Revive(bool),
    /// Cure a specific status condition.
    CurePoison,
    CureBurn,
    CureFreeze,
    CureSleep,
    CureParalysis,
    /// Cure any status condition (Full Heal).
    CureAllStatus,
    /// Permanently boost a stat via vitamin. Value is stat index: 0=HP, 1=Atk, etc.
    Vitamin(u8),
    /// Level up by one (Rare Candy).
    RareCandy,
    /// Boost a battle stat stage. Value is stat index.
    BattleStat(u8),
    /// Set a battle status2 flag (X Accuracy, Guard Spec., Dire Hit). Value is flag ID.
    BattleFlag(u8),
    /// Escape from wild battle (Poké Doll).
    Escape,
    /// Restore PP to a single move. `true` = full restore (Max Ether).
    PpRestoreSingle(bool),
    /// Restore PP to all moves. `true` = full restore (Max Elixir).
    PpRestoreAll(bool),
    /// Apply a PP Up to one move.
    PpUp,
    /// Evolution stone. Value: 0=Moon, 1=Fire, 2=Thunder, 3=Water, 4=Leaf.
    EvolutionStone(u8),
    /// No combat/field effect — key item, badge, etc.
    None,
}

