#[cfg(test)]
mod item_kind_tests {
    use super::*;

    #[test]
    fn potion_is_consumable() {
        assert_eq!(item_kind(ItemId::Potion), ItemKind::Consumable);
    }

    #[test]
    fn master_ball_is_custom() {
        assert_eq!(
            item_kind(ItemId::MasterBall),
            ItemKind::Custom(CustomKind::Ball)
        );
    }

    #[test]
    fn bicycle_is_key_item() {
        assert_eq!(item_kind(ItemId::Bicycle), ItemKind::KeyItem);
    }

    #[test]
    fn rare_candy_is_stat_boost() {
        assert_eq!(item_kind(ItemId::RareCandy), ItemKind::StatBoost);
    }

    #[test]
    fn moon_stone_is_evolution() {
        assert_eq!(item_kind(ItemId::MoonStone), ItemKind::Evolution);
    }

    #[test]
    fn nugget_is_currency() {
        assert_eq!(item_kind(ItemId::Nugget), ItemKind::Currency);
    }

    #[test]
    fn full_restore_is_consumable() {
        assert_eq!(item_kind(ItemId::FullRestore), ItemKind::Consumable);
    }

    #[test]
    fn escape_rope_is_consumable() {
        assert_eq!(item_kind(ItemId::EscapeRope), ItemKind::Consumable);
    }

    #[test]
    fn protein_is_stat_boost() {
        assert_eq!(item_kind(ItemId::Protein), ItemKind::StatBoost);
    }

    #[test]
    fn great_ball_is_custom_ball() {
        assert_eq!(
            item_kind(ItemId::GreatBall),
            ItemKind::Custom(CustomKind::Ball)
        );
    }

    #[test]
    fn badge_is_key_item() {
        assert_eq!(item_kind(ItemId::BoulderBadge), ItemKind::KeyItem);
    }

    #[test]
    fn coin_case_is_key_item() {
        assert_eq!(item_kind(ItemId::CoinCase), ItemKind::KeyItem);
    }

    #[test]
    fn elixer_is_consumable() {
        assert_eq!(item_kind(ItemId::Elixer), ItemKind::Consumable);
    }

    #[test]
    fn guard_spec_is_consumable() {
        assert_eq!(item_kind(ItemId::GuardSpec), ItemKind::Consumable);
    }
}

#[cfg(test)]
mod const_name_tests {
    use super::item_kind;
    use super::ItemId;
    use crate::items::CustomKind;
    use jrpg_engine::items::ItemKind;

    #[test]
    fn const_name_key_items() {
        assert_eq!(ItemId::OaksParcel.const_name(), "OAKS_PARCEL");
        assert_eq!(ItemId::PokeBall.const_name(), "POKE_BALL");
        assert_eq!(ItemId::SilphScope.const_name(), "SILPH_SCOPE");
        assert_eq!(ItemId::LiftKey.const_name(), "LIFT_KEY");
        assert_eq!(ItemId::TownMap.const_name(), "TOWN_MAP");
    }

    #[test]
    fn from_const_name_round_trips() {
        for item in [
            ItemId::OaksParcel,
            ItemId::PokeBall,
            ItemId::SilphScope,
            ItemId::LiftKey,
            ItemId::TownMap,
            ItemId::CardKey,
            ItemId::SsTicket,
            ItemId::Nugget,
        ] {
            assert_eq!(
                ItemId::from_const_name(&item.const_name()),
                Some(item),
                "round-trip failed for {:?}",
                item,
            );
        }
    }

    #[test]
    fn from_const_name_unknown_is_none() {
        assert_eq!(ItemId::from_const_name("NOT_A_REAL_ITEM"), None);
        // NoItem must never be resolvable by name.
        assert_eq!(ItemId::from_const_name("NO_ITEM"), None);
    }

    #[test]
    fn from_const_name_is_underscore_insensitive() {
        // Scripts authored from asm constants may drop the case-boundary '_';
        // both spellings must resolve to the same item.
        assert_eq!(ItemId::HpUp.const_name(), "HP_UP");
        assert_eq!(ItemId::from_const_name("HPUP"), Some(ItemId::HpUp));
        assert_eq!(ItemId::from_const_name("HP_UP"), Some(ItemId::HpUp));
    }

    /// TMs/HMs resolve to the bag-storable ItemId variants (ids $C4-$FA).
    #[test]
    fn tms_and_hms_resolve_from_const_name() {
        assert_eq!(ItemId::from_const_name("TM34"), Some(ItemId::Tm34));
        assert_eq!(ItemId::from_const_name("TM_13"), Some(ItemId::Tm13));
        assert_eq!(ItemId::from_const_name("TM01"), Some(ItemId::Tm01));
        assert_eq!(ItemId::from_const_name("TM50"), Some(ItemId::Tm50));
        assert_eq!(ItemId::from_const_name("HM03"), Some(ItemId::Hm03));
        // Round-trip const_name.
        assert_eq!(ItemId::Tm34.const_name(), "TM_34");
        assert_eq!(ItemId::from_const_name(&ItemId::Tm34.const_name()), Some(ItemId::Tm34));
        // Item ids match the original GB table (TM01 = $C9, HM01 = $C4).
        assert_eq!(ItemId::Tm01 as u8, 0xC9);
        assert_eq!(ItemId::Tm50 as u8, 0xFA);
        assert_eq!(ItemId::Hm01 as u8, 0xC4);
    }

    /// TMs are categorized as Custom(Tm) so they are not treated as key items.
    #[test]
    fn tm_item_kind_is_custom() {
        assert!(matches!(
            item_kind(ItemId::Tm27),
            ItemKind::Custom(CustomKind::Tm)
        ));
        assert!(matches!(
            item_kind(ItemId::Hm03),
            ItemKind::Custom(CustomKind::Hm)
        ));
    }
}
